"""Phase 3: assemble notes/phase3.md from saved outputs (data/processed/phase3/*.json, with phase2 as the baseline). python -I scripts/p3_05_write_notes.py"""
import json
import os
import sys

sys.path.insert(0, os.getcwd())
import numpy as np
from scipy.stats import beta

P2, P3 = "data/processed/phase2/", "data/processed/phase3/"
J = lambda p: json.load(open(p))
CV, SEL, FE, C3, C2, X3, X2 = J(P3 + "cv_results.json"), J(P3 + "selected.json"), J(P3 + "final_eval.json"), J(P3 + "conformal.json"), J(P2 + "conformal.json"), J(P3 + "cascade.json"), J(P2 + "cascade.json")
TASKS = ("thermal", "solvent", "water")
ci = lambda t, d=3: f"{t[0]:.{d}f} [{t[1]:.{d}f}, {t[2]:.{d}f}]"
sci = lambda t, d=3: f"{t[0]:+.{d}f} [{t[1]:+.{d}f}, {t[2]:+.{d}f}]"
pc = lambda x: f"{100 * x:.1f}%"
cname = lambda c: ", ".join(f"{k}={v}" for k, v in c.items())


def cp(k, n, level=0.95):
    lo = 0.0 if k == 0 else beta.ppf((1 - level) / 2, k, n - k + 1)
    hi = 1.0 if k == n else beta.ppf(1 - (1 - level) / 2, k + 1, n - k)
    return lo, hi


L = []
w = L.append
w("# Phase 3: trying to improve group-aware discrimination, and re-running the conformal analysis")
w("")
w("Generated by `scripts/p3_05_write_notes.py` from saved results; producing scripts: `p3_01_select.py` (model selection), `p3_02_final_eval.py` (test comparison), `p3_03_conformal.py`, `p3_04_cascade.py`; model code `src/models/boosted.py` (tests in `tests/test_boosted.py`). Outputs are in `data/processed/phase3/`. Baselines are the Phase 2 results (`notes/phase2.md`) on the same group splits and the same test MOFs.")
w("")
w("## 0. What was done, and what to keep in mind")
w("")
w("- **No test tuning.** Model selection (`p3_01`) uses 5-fold *group* cross-validation on the **training groups only**; calibration and test MOFs are not read there (asserted in the script). The test split is first used in `p3_02`, after `selected.json` was written. Selection metric: pooled out-of-fold AUC for 'truly stable'. I did not iterate on test results; the configurations were fixed before looking at them.")
w("- **Candidates:** XGBoost (depth 3/5/7, min child weight 1/5, 400 trees, learning rate 0.05; for thermal squared vs absolute error loss), ExtraTrees and RandomForest (500 trees, min leaf 1/3), each with and without **in-fold feature selection** (top 50 features by XGBoost gain, fitted on the training rows of each fold), and for the two classification tasks with and without **balanced class weights**. Small ensemble = mean of the top-3 configurations by CV AUC. 'Single' vs 'ensemble' was also decided by CV AUC. LightGBM is not installed in the environment, so XGBoost stands in for gradient boosting.")
w("- **The same Phase 2 group splits** (60/20/20, proxy groups from refcode family and DOI). Trees are refit on all training groups (no early-stopping validation set is needed), 5 training seeds.")
w("- **The Phase 3 selected models are used in every downstream step for all three stages, decided before the test comparison**, including water, where the test comparison turned out not to be an improvement (section 2).")
w("- The cascade (section 4) re-uses the configurations selected in `p3_01` inside every cross-fitting fold. Those configurations were chosen using the training groups of the single split, and some of those MOFs are in the held-out folds of the cascade, so there is a small selection leak into the cascade evaluation (configuration level, not parameter level).")
w("")
w("## 1. Cross-validation on the training groups")
w("")
for t in TASKS:
    r = CV[t]; rows = r["configs"]; s = SEL[t]
    mk = [k for k in rows[0] if k not in ("config", "cfg", "AUC_stable")][0]
    w(f"**{t}** ({r['n_train']} training MOFs, {r['n_train_groups']} groups). Top 5 of {len(rows)} configurations by CV AUC (stable):")
    w("")
    w(f"| configuration | CV AUC (stable) | CV {mk} |")
    w("|---|---|---|")
    for x in rows[:5]:
        w(f"| {x['config']} | {x['AUC_stable']:.3f} | {x[mk]:.3f} |")
    best = lambda f: max((x["AUC_stable"] for x in rows if f(x["cfg"])), default=float("nan"))
    parts = [f"by model family: " + ", ".join(f"{k} {best(lambda c, k=k: c['kind'] == k):.3f}" for k in ("xgb", "et", "rf")),
             f"feature selection (top 50) {best(lambda c: c['fs'] == 50):.3f} vs none {best(lambda c: not c['fs']):.3f}"]
    if t != "thermal":
        parts.append(f"balanced class weights {best(lambda c: c.get('balanced') is True):.3f} vs unweighted {best(lambda c: c.get('balanced') is False):.3f}")
    w("")
    w("Best CV AUC: " + "; ".join(parts) + ".")
    w("")
    w(f"Best single: CV AUC {s['cv_single']['AUC_stable']:.3f}; top-3 mean: CV AUC {s['cv_ensemble']['AUC_stable']:.3f}; **chosen: {s['choice']}** ({'; '.join(cname(c) for c in (s['ensemble'] if s['choice'] == 'ensemble' else [s['single']]))}).")
    w("")
w("Differences of a few thousandths in CV AUC between neighbouring configurations are within CV noise, so the specific winners should not be over-interpreted.")
w("")
w("## 2. Test comparison against the Phase 2 baselines (group-aware test sets)")
w("")
w("Seed 0; 95% percentile intervals from a bootstrap over **groups** (1,000 resamples). 'Difference' is new minus baseline on the identical resampled MOFs, so its interval is paired and narrower than the difference of the two separate intervals suggests. Baselines: thermal and solvent = released neural networks with the fixed early-stopping restore; water = released random forest settings (Phase 2).")
w("")
w("| task | metric | Phase 2 baseline | Phase 3 | difference (paired) | 5-seed mean +- sd (Phase 3) |")
w("|---|---|---|---|---|---|")
for t in TASKS:
    f = FE[t]
    for k in f["new"]:
        w(f"| {t} ({f['choice']}, n_test {f['n_test']}) | {k} | {ci(f['baseline'][k])} | {ci(f['new'][k])} | {sci(f['diff'][k])} | {f['seeds_mean'][k]:.3f} +- {f['seeds_sd'][k]:.3f} |")
w("")
th, so, wa = FE["thermal"], FE["solvent"], FE["water"]
w("**Reading.**")
w(f"- **Thermal improved:** AUC {th['diff']['AUC_stable'][0]:+.3f} (paired interval [{th['diff']['AUC_stable'][1]:+.3f}, {th['diff']['AUC_stable'][2]:+.3f}]), MAE {th['diff']['MAE_degC'][0]:+.1f} degC ([{th['diff']['MAE_degC'][1]:+.1f}, {th['diff']['MAE_degC'][2]:+.1f}]); the accuracy gain's interval includes zero.")
w(f"- **Solvent: no detectable change.** AUC {so['diff']['AUC'][0]:+.3f} with an interval that includes zero ([{so['diff']['AUC'][1]:+.3f}, {so['diff']['AUC'][2]:+.3f}]); accuracy is identical at the point estimate. Group-aware CV AUC for every candidate was low (best {SEL['solvent']['cv_ensemble']['AUC_stable']:.3f}), so the solvent labels carry little signal that transfers to unseen groups with these features.")
w(f"- **Water: no improvement, nominally worse.** AUC {wa['diff']['AUC_stable'][0]:+.3f} ([{wa['diff']['AUC_stable'][1]:+.3f}, {wa['diff']['AUC_stable'][2]:+.3f}]), 4-class accuracy {wa['diff']['accuracy_4class'][0]:+.3f}; both intervals include zero, so this is no evidence of a difference, and it is certainly no gain. The CV winner did not beat the released random-forest recipe on this test set.")
w("- In CV, in-fold feature selection gave the highest AUC in all three tasks, but only by 0.003-0.019 over no selection; balanced class weights gave no CV gain (see section 1). I did not try neural-network ensembles, richer features, or MOFid-based features in this phase.")
w("")
w("## 3. Per-stage conformal recall control with the Phase 3 models")
w("")
w("Same procedure as Phase 2 section 3 (calibration MOFs are whole held-out groups; threshold = k-th smallest calibration-positive score, k = floor(alpha (n+1))). Kept fraction = share of ALL group-aware test MOFs that pass. Intervals: bootstrap over test groups, threshold fixed.")
w("")
for t in TASKS:
    a, b = C2[f"group_{t}"], C3[f"group_{t}"]
    w(f"**{t}** — Phase 2 baseline vs Phase 3 (calibration positives {a['n_cal_pos']} vs {b['n_cal_pos']}; test positives {a['n_test_pos']} / {b['n_test_pos']} of {b['n_test']}). Paper's fixed rule, Phase 3 model: recall {b['paper_rule']['recall']:.3f}, kept {b['paper_rule']['kept_fraction']:.3f}.")
    w("")
    w("| target recall | baseline: test recall | baseline: kept [95% CI] | Phase 3: test recall [95% CI] | Phase 3: kept [95% CI] | change in kept |")
    w("|---|---|---|---|---|---|")
    for ra, rb in zip(a["curve"], b["curve"]):
        w(f"| {rb['target_recall']:.2f} | {ra['recall']:.3f} | {ra['kept_fraction']:.3f} [{ra['kept_lo']:.3f}, {ra['kept_hi']:.3f}] | {rb['recall']:.3f} [{rb['recall_lo']:.3f}, {rb['recall_hi']:.3f}] | {rb['kept_fraction']:.3f} [{rb['kept_lo']:.3f}, {rb['kept_hi']:.3f}] | {rb['kept_fraction'] - ra['kept_fraction']:+.3f} |")
    w("")
w("Test recall differs between the two columns because each is a single calibration draw; the validity check below shows how much a single draw varies. The 'change in kept' column compares different calibration thresholds and different test recalls, so a lower kept fraction at a lower realised recall is not a like-for-like gain; compare at (near-)equal realised recall.")
w("")
w("### Validity over re-partitions, plain and PAC (training-conditional)")
w("")
w("500 random re-partitions of the pooled calibration+test groups into calibration/test with scores fixed (as in Phase 2). PAC variant: threshold from the Beta(k, n-k+1) argument with delta = 0.1, which would, if its assumptions held, reach the target in at least 90% of calibration draws.")
w("")
w("| task | alpha | target | plain: mean recall | plain: partitions >= target | plain: kept | PAC: mean recall | PAC: partitions >= target | PAC: kept | baseline plain / PAC partitions >= target |")
w("|---|---|---|---|---|---|---|---|---|---|")
for t in TASKS:
    b, a = C3[f"group_{t}"], C2[f"group_{t}"]
    for v, pa, v0, pa0 in zip(b["validity"], b["pac"], a["validity"], a["pac"]):
        pv = pa["valid"]
        w(f"| {t} | {v['alpha']:.2f} | {v['target']:.2f} | {v['mean_recall']:.3f} | {pc(v['frac_reps_at_or_above_target'])} | {v['mean_kept_fraction']:.3f} | {pv['mean_recall']:.3f} | {pc(pv['frac_reps_at_or_above_target'])} | {pv['mean_kept_fraction']:.3f} | {pc(v0['frac_reps_at_or_above_target'])} / {pc(pa0['valid']['frac_reps_at_or_above_target'])} |")
w("")
gp = [pa["valid"]["frac_reps_at_or_above_target"] for t in TASKS for pa in C3[f"group_{t}"]["pac"]]
w(f"**The PAC (training-conditional) guarantee is NOT verified.** The fraction of partitions reaching the target is {pc(min(gp))}-{pc(max(gp))} across cells; the nominal value is at least 90%, and some cells are below it. This check is itself noisy (finite test sets with few positives; the partitions overlap, so the 500 repetitions are not independent; and groups introduce dependence that violates the i.i.d. assumption behind the Beta argument). Only the marginal guarantee (expected recall >= 1 - alpha) is supported by the numbers, and for that the mean realised recall is within {max(abs(v['mean_recall'] - v['target']) for t in TASKS for v in C3[f'group_{t}']['validity']):.3f} of the target in every cell.")
w("")
w("## 4. Cascade with the Phase 3 models (union bound, 92 labelled MOFs)")
w("")
R3, R2, A = X3["results"], X2["results"], X3["alphas"]
n_all = R3[0]["n_all_stable"]
w(f"Same design as Phase 2 section 4 (group cross-fitting, K = {X3['K']}, {len(X3['reps'])} repetitions; {R3[0]['n_labelled']} labelled MOFs, {n_all} stable at all three stages). The five repetitions share the same MOFs and are not independent tests.")
w("")
w("**Per-stage out-of-fold coverage and kept fraction** (all out-of-fold MOFs; Phase 2 baseline in brackets):")
w("")
w("| stage | " + " | ".join(f"alpha {a:.2f}: recall / kept" for a in A) + " |")
w("|---|" + "---|" * len(A))
for t in TASKS:
    cells = []
    for a in A:
        f = lambda R, k: np.mean([r["stage"][t][str(a)][k] for r in R])
        cells.append(f"{f(R3, 'recall'):.3f} / {f(R3, 'kept'):.3f} ({f(R2, 'recall'):.3f} / {f(R2, 'kept'):.3f})")
    w(f"| {t} | " + " | ".join(cells) + " |")
w("")
w("**Cascade on the 92 labelled MOFs.** Recall = share of the 17 all-stable MOFs that pass; kept = share of all 92; false pass = share of the 75 others.")
w("")
w("| rule | alpha | target | passes per repetition (of 17), Phase 3 | recall: Phase 3 (baseline) | kept: Phase 3 (baseline) | false pass: Phase 3 (baseline) | 95% Clopper-Pearson, Phase 3 mean count |")
w("|---|---|---|---|---|---|---|---|")
for kind, label in (("union", "union bound, alpha/3 per stage"), ("each_alpha", "no union bound, alpha per stage")):
    for a in A:
        k = f"{kind}_{a}"; g = lambda R, f: np.mean([r["cascade"][k][f] for r in R])
        cnt = [r["cascade"][k]["n_pass_pos"] for r in R3]; lo, hi = cp(int(round(np.mean(cnt))), n_all)
        w(f"| {label} | {a:.2f} | {1 - a:.2f} | {', '.join(map(str, cnt))} | {g(R3, 'recall'):.3f} ({g(R2, 'recall'):.3f}) | {g(R3, 'kept'):.3f} ({g(R2, 'kept'):.3f}) | {g(R3, 'false_pass_rate'):.3f} ({g(R2, 'false_pass_rate'):.3f}) | [{lo:.2f}, {hi:.2f}] |")
pr3, pr2 = [r["cascade"]["paper_rules"] for r in R3], [r["cascade"]["paper_rules"] for r in R2]
w(f"| paper's fixed rules | | | {', '.join(str(r['n_pass_pos']) for r in pr3)} | {np.mean([r['recall'] for r in pr3]):.3f} ({np.mean([r['recall'] for r in pr2]):.3f}) | {np.mean([r['kept'] for r in pr3]):.3f} ({np.mean([r['kept'] for r in pr2]):.3f}) | {np.mean([r['false_pass_rate'] for r in pr3]):.3f} ({np.mean([r['false_pass_rate'] for r in pr2]):.3f}) | |")
w("")
u = lambda R, a, f: np.mean([r["cascade"][f"union_{a}"][f] for r in R])
w("**Honest reading.**")
w("- With the union bound, mean recall on the 17 all-stable MOFs is " + ", ".join(f"{u(R3, a, 'recall'):.3f}" for a in A) + " for targets " + ", ".join(f"{1 - a:.2f}" for a in A) + ". As in Phase 2 the 95% intervals are wide because there are only 17 positives: the data are consistent with the guarantee but cannot confirm it.")
w("- Kept fraction of the cascade (union bound), Phase 3 vs baseline: " + "; ".join(f"target {1 - a:.2f}: {u(R3, a, 'kept'):.3f} vs {u(R2, a, 'kept'):.3f}" for a in A) + ". The kept fraction is identical at target 0.95 and lower with the Phase 3 models at the lower targets. At the matching recall levels the cascade recall on the 17 positives is higher at targets 0.95 and 0.90 and slightly lower at 0.80 and 0.70, so these are not like-for-like comparisons, and with 17 positives the differences are within the noise (repetitions share the same MOFs).")
w("- The larger, more reliable comparison is the per-stage out-of-fold table above (thousands of MOFs): at each alpha the thermal stage keeps fewer MOFs (e.g. alpha 0.10: 0.711 vs 0.797) at a slightly lower realised recall (0.889 vs 0.906), the solvent stage keeps slightly fewer, and the water stage is unchanged. I did not run a significance test on these differences or a per-stage attribution of the cascade change.")
w("")
w("## 5. Limitations")
w("")
w("- Proxy groups, not MOFid groups (see Phase 2). Labels are the released labels.")
w("- The only clear gain is for the thermal stage; solvent and water are essentially unchanged in group-aware discrimination, which suggests the limit is the features/labels rather than the model class. Untried: graph neural networks on structures, richer descriptors, and an external validation set.")
w("- Intervals are from 1,000 group-bootstrap resamples on a single split of 589 / 425 / 232 test MOFs; a different group split could give different numbers.")
w("- The PAC variant is unverified (section 3). The cascade rests on 17 positives.")
w("- Candidate set and grid were chosen by me before running and are small; I did not tune hyperparameters beyond that grid.")
open("notes/phase3.md", "w").write("\n".join(L) + "\n")
print("written notes/phase3.md,", len(L), "lines")
